local g = {} g.last = gg.getFile() g.info = nil g.config = gg.getFile():gsub('%lua$', '')..'cfg' g.data = loadfile(g.config) if g.data ~= nil then g.info = g.data() g.data = nil end if g.info == nil then g.info = {g.last, g.last:gsub('/[^/]+$', ''),gg.VERSION} end if g.info[3] == nil then g.info[3] = gg.VERSION end  while true do g.info = gg.prompt({'选择运行脚本:', '选择输出文件夹:', '运行时使用GG版本号(跳过专属修改器检查):'}, g.info, {'file', 'path', 'text'}) if g.info == nil then break end gg.saveVariable(g.info, g.config) local filepath=g.info[1] gg.VERSION = g.info[3] gg.VERSION_INT = tonumber((gg.VERSION:gsub('%.[0-9]+', function (m) m = m:sub(2) if #m == 1 then m = '0'..m end return m end))) g.last = g.info[1] g.test = loadfile(g.last) if g.test == nil then gg.alert('载入脚本错误,请检查脚本是否错误.'..g.last) else g.name = g.last:match('[^/]+$') g.pathes = {g.info[2]..'/'..g.name, g.last, '/sdcard/'..g.name, gg.getFile():gsub('[^/]+$', '')..g.name, gg.EXT_FILES_DIR..'/'..g.name} g.file = nil g.out = '' g.try = '' for i, v in ipairs(g.pathes) do g.out = v..".tmp.lua" g.file = io.open(g.out, "w") if g.file ~= nil then g.last = v:gsub('%.lua$', '') break end g.try = g.try..' '..v end if g.file == nil then gg.alert('写出文件失败,请检查:'..g.try) else g.file:close() os.remove(g.out) g.sel = gg.choice({ '反编译LUA字节码', 'GG函数拦截', }) if g.sel == nil then break end if g.sel == 1 then g.out = g.last..".dump.txt" g.res = gg.internal2(g.test, g.out) if g.res then gg.alert('已写出到文件:\n'..g.out) break else gg.alert('反编译时候出现异常:\n'..g.res) end elseif g.sel == 2 then if true then local ggg = {} local otoast=gg.toast for k, v in pairs(gg) do ggg[k] = v end local sel = select local typ = type local str = tostring local echo = print local io_open = io.open local tr = {} local msg = '' if true then local file =g.last..'.hook' local f = io_open(file, 'w') f:write("----GG拦截器,ONLY深度优化.\n") f:close() local names = { setRanges = {'^REGION_'}, startFuzzy = {'^TYPE_', '0x%X', '0x%X'}, searchAddress = {nil, '0x%X', '^TYPE_', '^SIGN_[^F]', '0x%X', '0x%X'}, searchFuzzy = {nil, '^SIGN_FUZZY_', '^TYPE_', '0x%X', '0x%X'}, searchNumber = {nil, '^TYPE_', nil, '^SIGN_[^F]', '0x%X', '0x%X'}, loadList = {nil, '^LOAD_'}, saveList = {nil, '^SAVE_'}, editAll = {nil, '^TYPE_'}, copyMemory = {'0x%X', '0x%X'}, dumpMemory = {'0x%X', '0x%X'}, } local rets = { alert = 1, prompt = 1, choice = 1, multiChoice = 1, } local toFlags = function (check, value) local ret = '' for k, v in pairs(ggg) do if k:match(check) ~= nil and (value & v) == v then if ret ~= '' then ret = ret..' | ' end ret = ret..'gg.'..k value = value & ~v end end if ret == '' or value ~= 0 then if ret ~= '' then ret = ret..' | ' end ret = ret..value end return ret end for i, v in pairs(ggg) do if typ(v) == 'function' and i ~= 'getLine' and i ~= 'isVisible' and i~='multichoice' and i~='prompt' and i~='setVisible' then local orig = v local name = i local hook = 1 if i=='choice' then hook = function (...) local arg = {...} local list=arg[1] local f = io_open(file, 'a') local index= orig(...) f:write("\n------"..list[index].."-------\n") f:close() return index end elseif i=='getFile' then hook=function() return filepath end else hook = function (...) local arg = {...} local f = io_open(file, 'a') if name=='clearResults' then f:write('\n\ngg.'..name..'(') else f:write('gg.'..name..'(') end for j, a in ipairs(arg) do if j ~= 1 then f:write(', ') end if typ(a) == 'string' then f:write('"') end local b = a if typ(a) == 'number' and names[name] ~= nil and names[name][j] ~= nil then local check = names[name][j] if check:sub(1, 1) ~= '^' then if a == 0 or a == -1 then b = a else b = check:format(a) end else b = toFlags(check, a) end end b = str(b) f:write(b) if typ(a) == 'string' then f:write('"') end end f:write(")") if rets[name] ~= nil then local ret = orig(...) f:write(" --[[ ") f:write(str(ret)) f:write(" ]]\n") f:close() return ret end f:write("\n") f:close() if name=='alert' or name=='getResults' or name=='setRanges' or name=='editAll' then return nil elseif name==